"""Buyer-facing pages: one brand, three distinct ways to discover its projects."""
from build import ROOT, t, a, btn, head, nav, footer, proposal

PROJECTS = [
    ('pixel', 'Pixel', 'La Magdalena', 'pixel-exterior-render', '/pixel/', 'Estudios, suites y departamentos.', 'Studios, suites and apartments.'),
    ('magnus', 'Magnus', 'Quito', 'magnus-night-render', 'https://alphabuildershq.com/magnus/', 'Una silueta que transforma el horizonte.', 'A silhouette that reshapes the skyline.'),
    ('sparta', 'Sparta', 'Av. Bélgica y Shyris', 'sparta-exterior-render', 'https://alphabuildershq.com/proyecto-sparta/', 'La arquitectura se encuentra con la ciudad.', 'Where architecture meets the city.'),
]


def photo(asset, alt, cls='', eager=False):
    return f'<img class="{cls}" src="/assets/{asset}.png" alt="{alt}" loading="{"eager" if eager else "lazy"}" decoding="async">'


def demo_entry():
    return a('Probar la demo 3D','Try the 3D demo','/pixel/?demo=3d#demo-3d','button demo-primary','data-demo3d')


def direction(key, content, cls=''):
    return f'<section class="direction-view {cls}" data-direction="{key}">{content}</section>'


def project_cards():
    return ''.join(f'''<article class="discovery-card" data-project-card="{slug}"><a href="{url}" {'target="_blank" rel="noopener"' if slug != 'pixel' else ''}><figure>{photo(img, 'Render conceptual · IA de '+name)}<figcaption><span>0{i+1}</span><span>{t('Render conceptual · IA','Concept render · AI')}</span></figcaption></figure><div class="discovery-card-copy"><span class="place-label">{sector if sector=='Quito' else sector+' · Quito'}</span><h3>{name}</h3><p>{t(es,en)}</p><span class="card-link">{t('Conocer Pixel','Discover Pixel') if slug=='pixel' else t('Ver sitio del proyecto','Visit the project website')}</span></div></a></article>''' for i,(slug,name,sector,img,url,es,en) in enumerate(PROJECTS))


def home():
    essential = f'''<div class="essential-intro"><span class="overline">ALPHA BUILDERS · QUITO</span>{t('Encuentra tu<br>próximo <em>lugar.</em>','Find your<br>next <em>place.</em>','h1')}<p>{t('Conoce nuestros proyectos, encuentra su ubicación y conecta con el equipo de cada uno.','Explore our projects, find their location and connect with each project’s team.')}</p><div class="action-row">{a('Ver proyectos','Browse projects','#projects','button')}{a('Conocer Pixel','Discover Pixel','/pixel/','text-link')}</div><dl class="intro-facts"><div><dt>{t('CIUDAD','CITY')}</dt><dd>Quito</dd></div><div><dt>{t('EN ESTA SELECCIÓN','IN THIS SELECTION')}</dt><dd>{t('3 proyectos','3 projects')}</dd></div></dl></div><figure class="essential-image">{photo('pixel-exterior-render','Fachada de Pixel, La Magdalena',eager=True)}<figcaption>PIXEL · LA MAGDALENA</figcaption></figure>'''
    editorial = f'''<div class="editorial-masthead"><span>{t('ARQUITECTURA & VIDA URBANA','ARCHITECTURE & URBAN LIFE')}</span><span>QUITO / 01</span></div><div class="editorial-title">{t('Formas de<br><em>habitar.</em>','Ways of<br><em>living.</em>','h1')}<p>{t('Una mirada a los lugares que elegimos para vivir. Empezamos por Pixel, en La Magdalena.','A closer look at the places we choose to call home. We begin with Pixel, in La Magdalena.')}</p><div class="action-row">{a('Ver proyectos','Browse projects','#projects','button')}</div></div><figure class="editorial-cover">{photo('pixel-exterior-render','La fachada de Pixel y sus balcones',eager=True)}<figcaption><b>01 / PIXEL</b><span>{t('Color, ciudad y vida cotidiana.','Colour, city and everyday life.')}</span></figcaption></figure><div class="editorial-margin" aria-hidden="true">ALPHA<br>BUILDERS</div>'''
    immersive = f'''<div class="immersive-scenes">{''.join(f'<div class="immersive-scene" data-scene-home="{slug}"'+('' if i==0 else ' hidden')+f'>{photo("pixel-living-render" if slug=="pixel" else img, "Visualización de "+name,eager=i==0)}</div>' for i,(slug,name,sector,img,*_) in enumerate(PROJECTS))}</div><div class="immersive-cover-copy"><span class="overline">{t('UN LUGAR PARA IMAGINARTE','A PLACE TO PICTURE YOURSELF')}</span>{t('Tu próxima<br>historia empieza<br><em>aquí.</em>','Your next<br>chapter starts<br><em>here.</em>','h1')}<p id="featured-description">{t('Entra a Pixel. Descubre sus espacios y explora una nueva forma de elegir tu hogar.','Step inside Pixel. Discover its spaces and a new way to choose your home.')}</p><div class="action-row">{a('Ver proyectos','Browse projects','#projects','button')}<a class="text-link" id="featured-link" href="/pixel/">{t('Entrar a Pixel','Enter Pixel')}</a></div></div><span class="immersive-image-note">{t('Renders conceptuales · IA','Concept renders · AI')}</span>'''
    out=head()+nav()+f'''<main id="main" class="discovery-home">{direction('essential',essential,'home-essential')}{direction('editorial',editorial,'home-editorial')}{direction('immersive',immersive,'home-immersive')}<section class="discovery-projects" id="projects"><div class="discovery-section-head"><span class="overline">{t('EXPLORA QUITO','EXPLORE QUITO')}</span><h2><span class="direction-copy" data-for="essential">{t('Elige por dónde empezar.','Choose where to begin.')}</span><span class="direction-copy" data-for="editorial">{t('Tres proyectos.<br>Tres miradas.','Three projects.<br>Three perspectives.')}</span><span class="direction-copy" data-for="immersive">{t('Sigue explorando.','Keep exploring.')}</span></h2><p>{t('Cada proyecto tiene su propio lugar en la ciudad. Conoce su arquitectura y encuentra al equipo que puede ayudarte.','Every project has its own place in the city. Discover its architecture and find the team who can help you.')}</p></div><div class="discovery-grid">{project_cards()}</div></section><section class="discovery-closing" id="vision"><span class="overline">ALPHA BUILDERS</span>{t('La ciudad es el contexto.<br><em>Tu vida, el punto de partida.</em>','The city is the setting.<br><em>Your life is the starting point.</em>','h2')}<div><p>{t('La ubicación, los espacios y la manera de vivirlos hacen diferente a cada hogar. En Pixel puedes conocer las tipologías, recorrer sus ambientes y conversar con el equipo del proyecto.','Location, spaces and the way you use them make every home different. At Pixel, explore the home types, discover its spaces and speak with the project team.')}</p>{a('Descubrir Pixel','Discover Pixel','/pixel/','button')}</div></section><section id="contact" class="buyer-contact"><span class="overline">{t('HABLEMOS DE TU PRÓXIMO HOGAR','LET’S TALK ABOUT YOUR NEXT HOME')}</span>{t('¿Qué proyecto te interesa?','Which project interests you?','h2')}<p>{t('Elige un proyecto para contactar a su equipo y consultar precios y disponibilidad.','Choose a project to contact its team and ask about pricing and availability.')}</p><div class="advisor-projects">{a('Pixel →','Pixel →','/pixel/#contact')}{a('Magnus ↗','Magnus ↗','https://alphabuildershq.com/magnus/','','target="_blank" rel="noopener"')}{a('Sparta ↗','Sparta ↗','https://alphabuildershq.com/proyecto-sparta/','','target="_blank" rel="noopener"')}</div></section></main>'''+footer()+'</body></html>'
    (ROOT/'index.html').write_text(out)


def project_explorer():
    import json
    from proforma import data, mid_panel, high_panel
    d=data();d['projects']=[p for p in d['projects'] if p['slug']=='pixel']
    feed=json.dumps(d,ensure_ascii=False)
    tabs=f'''<div class="pf-tabs js-only" role="tablist" aria-label="Vista de Pixel"><button id="tab-medio" data-tab="medio" role="tab" aria-selected="true" aria-controls="demo-medio">{t('Elegir en el plano','Choose on the plan')}</button><button id="tab-alto" data-tab="alto" role="tab" aria-selected="false" aria-controls="demo-alto">{t('Explorar el edificio','Explore the building')}</button></div>'''
    return f'''<section id="experience" class="project-experience"><div class="project-section-heading"><span class="overline">{t('EXPLORA LOS DEPARTAMENTOS','EXPLORE THE APARTMENTS')}</span>{t('Encuentra tu departamento.','Find your apartment.','h2')}<p>{t('Elige un piso y consulta los detalles de un departamento en el plano. También puedes hablar directamente con un asesor.','Choose a floor and view an apartment’s details on the plan. You can also speak directly with an advisor.')}</p></div><div class="project-explorer pf" id="project-explorer" data-project="pixel"><p class="inventory-notice"><b>{t('INVENTARIO ILUSTRATIVO','ILLUSTRATIVE INVENTORY')}</b>{t('Esta muestra usa unidades, superficies, precios y estados de ejemplo. La maqueta es esquemática; confirma la información comercial con el equipo de Pixel.','This preview uses sample units, floor areas, prices and statuses. The model is schematic; confirm sales information with the Pixel team.')}</p><div id="demo">{tabs}{mid_panel(d)}{high_panel(d)}</div></div><script type="application/json" id="demo-data">{feed}</script></section>'''


def project():
    from build import map_dialog, tour_dialog
    essential=f'''<div><span class="overline">PIXEL / LA MAGDALENA</span>{t('Un espacio<br>para tu <em>día a día.</em>','A space for<br>your <em>everyday.</em>','h1')}<p>{t('Estudios, suites y departamentos en la esquina de Av. 5 de Junio y Rodrigo de Chávez.','Studios, suites and apartments on the corner of Av. 5 de Junio and Rodrigo de Chávez.')}</p><div class="action-row">{a('Ver departamentos','View apartments','#homes','button')}{a('Consultar disponibilidad','Enquire about availability','#contact','text-link')}</div></div><figure>{photo('pixel-exterior-render','Fachada y balcones de Pixel',eager=True)}<figcaption>PIXEL · LA MAGDALENA, QUITO</figcaption></figure>'''
    editorial=f'''<div class="editorial-masthead"><span>PIXEL / LA MAGDALENA</span><span>{t('UN PROYECTO DE ALPHA BUILDERS','A PROJECT BY ALPHA BUILDERS')}</span></div><div class="pixel-editorial-title">{t('La vida<br>tiene otro<br><em>color.</em>','Life in<br>a different<br><em>colour.</em>','h1')}<p>{t('El color aparece en la fachada, se transforma en el lobby y acompaña la vida cotidiana. Una mirada a Pixel, en La Magdalena.','Colour appears on the façade, transforms in the lobby and accompanies everyday life. A closer look at Pixel, in La Magdalena.')}</p><div class="action-row">{a('Ver departamentos','View apartments','#homes','button')}</div></div><figure>{photo('pixel-lobby-render','Techo de colores del lobby Pixel Colors',eager=True)}<figcaption><b>01 / PIXEL COLORS</b><span>{t('Una bienvenida con identidad propia.','A welcome with its own identity.')}</span></figcaption></figure>'''
    immersive=f'''<div class="pixel-immersive-background">{photo('pixel-living-render','Sala, comedor y cocina de un departamento Pixel',eager=True)}</div><div class="pixel-immersive-copy"><span class="overline">PIXEL / LA MAGDALENA, QUITO</span>{t('Imagina<br>llegar a <em>casa.</em>','Imagine<br>coming <em>home.</em>','h1')}<p>{t('Del edificio a sus interiores. Encuentra un punto de vista, recorre los espacios y descubre dónde empieza tu historia.','From the building to its interiors. Find a perspective, explore the spaces and discover where your story begins.')}</p><div class="action-row">{a('Ver departamentos','View apartments','#homes','button')}{a('Conocer el proyecto','Explore the project','#details','text-link')}</div></div>'''
    facts=f'''<section class="pixel-facts" id="details"><div><span class="overline">{t('PIXEL, DE UN VISTAZO','PIXEL AT A GLANCE')}</span>{t('Lo que necesitas<br>para empezar.','What you need<br>to get started.','h2')}<p>{t('Conoce la ubicación y las opciones de vivienda. El equipo del proyecto confirma la disponibilidad y las condiciones de compra.','Discover the location and home types. The project team confirms availability and purchase terms.')}</p></div><dl><div><dt>{t('UBICACIÓN','LOCATION')}</dt><dd>La Magdalena, Quito</dd></div><div><dt>{t('VIVIENDAS','HOMES')}</dt><dd>{t('Estudios, suites y departamentos','Studios, suites and apartments')}</dd></div><div><dt>{t('ESPACIOS COMPARTIDOS','SHARED SPACES')}</dt><dd>Pixel Colors · Pixel Pool</dd></div><div><dt>{t('PRECIOS Y DISPONIBILIDAD','PRICES & AVAILABILITY')}</dt><dd>{a('Consultar con el equipo','Ask the team','#contact','inline-link')}</dd></div><div><dt>{t('ESTADO Y ENTREGA','STATUS & DELIVERY')}</dt><dd>{t('Confirmar con Pixel','Confirm with Pixel')}</dd></div></dl></section>'''
    homes=f'''<section class="pixel-homes" id="homes"><div class="project-section-heading"><span class="overline">{t('TU ESPACIO','YOUR SPACE')}</span>{t('Hay más de una forma<br>de sentirse en casa.','There’s more than one way<br>to feel at home.','h2')}<p>{t('Un ambiente integrado, un dormitorio independiente o espacio para compartir. Elige la distribución que quieres conocer.','An integrated space, a separate bedroom or room to share. Choose the layout you want to explore.')}</p></div><div class="pixel-home-types">'''+''.join(f'''<article><span class="home-type-number">0{i+1}</span>{t(es,en,'h3')}<p>{t(copy,copyen)}</p><a href="https://pixel.com.ec/tour360/{slug}/" target="_blank" rel="noopener" class="text-link">{t('Recorrer '+es.lower()+' en 360','Tour the '+en.lower()+' in 360')}</a>{a('Consultar esta tipología','Enquire about this type','#contact','home-enquiry',f'data-home-type="{key}"')}</article>''' for i,(key,es,en,copy,copyen,slug) in enumerate([('estudio','Estudio','Studio','Un ambiente integrado para organizar tu día a tu manera.','One integrated space to arrange your day your way.','studioNuevo'),('suite','Suite','Suite','Dormitorio independiente y área social: dos ritmos en un mismo hogar.','A separate bedroom and living area: two rhythms in one home.','suiteNuevo'),('departamento','Departamento','Apartment','Sala, comedor y cocina, con opciones de tres o cuatro ambientes.','Living, dining and kitchen areas, with three- or four-space options.','deparNuevo')]))+f'''</div><div class="pixel-interior-story"><figure>{photo('pixel-living-render','Interior de referencia de un departamento Pixel')}<figcaption>{t('Interior de referencia · Render conceptual · IA','Reference interior · Concept render · AI')}</figcaption></figure><div><span class="overline">{t('DENTRO DE TU HOGAR','INSIDE YOUR HOME')}</span>{t('Espacio para<br>lo cotidiano.','Room for<br>everyday life.','h3')}<p>{t('La sala, el comedor y la cocina comparten un ambiente. El ventanal enmarca la vista y conecta visualmente los espacios.','The living room, dining area and kitchen share an open space. The window frames the view and visually connects the rooms.')}</p>{btn('Ver secuencia de espacios','View the sequence of spaces','text-link js-only','data-open="tour"')}</div></div></section>'''
    amenities=f'''<section class="pixel-amenities" id="amenities"><div class="project-section-heading"><span class="overline">{t('LA VIDA COMPARTIDA','SHARED SPACES')}</span>{t('Más allá<br>de tu puerta.','Beyond<br>your front door.','h2')}<p>{t('Un lugar para llegar. Otro para hacer una pausa. Conoce los espacios compartidos de Pixel.','A place to arrive. Another to pause. Discover Pixel’s shared spaces.')}</p></div><div class="pixel-amenity-grid"><figure>{photo('pixel-lobby-render','Lobby Pixel Colors con techo de colores')}<figcaption><h3>Pixel Colors</h3><p>{t('El lobby y su composición de colores.','The lobby and its composition of colours.')}</p></figcaption></figure><figure>{photo('pixel-pool-water-render','Piscina cubierta Pixel Pool')}<figcaption><h3>Pixel Pool</h3><p>{t('Piscina cubierta con zona de descanso.','Indoor swimming pool with a lounge area.')}</p></figcaption></figure></div></section>'''
    from sector import location_section
    location=location_section()
    contact=f'''<section class="pixel-contact" id="contact"><div><span class="overline">{t('CONVERSA CON PIXEL','SPEAK WITH PIXEL')}</span>{t('Tu siguiente paso,<br><em>con toda la información.</em>','Your next step,<br><em>with the full picture.</em>','h2')}<p>{t('Consulta superficies, precios, disponibilidad y fecha de entrega con el equipo del proyecto.','Ask the project team about floor areas, prices, availability and delivery dates.')}</p><p id="home-interest" hidden role="status"></p></div><div class="pixel-contact-links"><a data-enquiry-email href="mailto:contacto@pixel.com.ec">{t("Escribir a un asesor","Email an advisor")}</a><a href="tel:+593996775283">(+593) 99 67 75 283</a>{a('Visitar el sitio oficial','Visit the official website','https://pixel.com.ec/','button','target="_blank" rel="noopener"')}<small>{t('Datos de contacto publicados por Pixel.','Contact details published by Pixel.')}</small></div></section>'''
    out=head('project')+nav(True)+f'<main id="main" class="discover-page">'+direction('essential',essential,'pixel-essential')+direction('editorial',editorial,'pixel-editorial')+direction('immersive',immersive,'pixel-immersive')+facts+homes+project_explorer()+amenities+location+contact+'</main>'+footer()+map_dialog()+tour_dialog()+'</body></html>'
    (ROOT/'pixel').mkdir(exist_ok=True);(ROOT/'pixel'/'index.html').write_text(out)
